// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;

import org.eclipse.rdf4j.query.impl.EmptyBindingSet;
import org.junit.jupiter.api.Test;

/**
 * Pure two-thread tests for the hedge exchange: ordered delivery across page boundaries, backpressure parking with
 * consumer-close unblocking, poison-pill exhaustion and failure propagation, and entry-slot restore on cursor close.
 */
class LmdbNativeHedgeExchangeTest {

	@Test
	void rowsFlowInOrderAcrossPageBoundaries() throws Exception {
		NativeSlotLayout layout = layout(2);
		RowState row = row(layout);
		LmdbNativeHedgeExchange exchange = new LmdbNativeHedgeExchange(2, 4, 2);
		Thread producer = new Thread(() -> {
			long[] slots = new long[2];
			for (int i = 0; i < 10; i++) {
				slots[0] = i;
				slots[1] = i * 100;
				assertTrue(exchange.offerRow(slots));
			}
			exchange.finish();
		});
		producer.start();
		List<Long> seen = new ArrayList<>();
		LmdbNativeHedgeExchange.NativeHedgeExchangeCursor cursor = new LmdbNativeHedgeExchange.NativeHedgeExchangeCursor(
				row, exchange);
		while (cursor.next()) {
			seen.add(row.slots[0]);
			assertEquals(row.slots[0] * 100, row.slots[1]);
		}
		producer.join(5_000);
		assertEquals(List.of(0L, 1L, 2L, 3L, 4L, 5L, 6L, 7L, 8L, 9L), seen);
		assertEquals(10L, exchange.producedRows());
		cursor.close();
	}

	@Test
	void aFullExchangeParksTheProducerAndConsumerCloseUnblocksIt() throws Exception {
		NativeSlotLayout layout = layout(1);
		RowState row = row(layout);
		// capacity: 1 page of 1 row + queue of 1 -> the second offer must park
		LmdbNativeHedgeExchange exchange = new LmdbNativeHedgeExchange(1, 1, 1);
		AtomicInteger offered = new AtomicInteger();
		AtomicBoolean producerStopped = new AtomicBoolean();
		CountDownLatch parked = new CountDownLatch(1);
		Thread producer = new Thread(() -> {
			long[] slots = new long[1];
			for (int i = 0; i < 100; i++) {
				slots[0] = i;
				parked.countDown();
				if (!exchange.offerRow(slots)) {
					producerStopped.set(true);
					return;
				}
				offered.incrementAndGet();
			}
		});
		producer.start();
		assertTrue(parked.await(5, TimeUnit.SECONDS));
		Thread.sleep(120L); // let the producer hit the full queue and park in the 50 ms offer loop
		assertTrue(offered.get() <= 2, "the bounded exchange must park an unconsumed producer");
		LmdbNativeHedgeExchange.NativeHedgeExchangeCursor cursor = new LmdbNativeHedgeExchange.NativeHedgeExchangeCursor(
				row, exchange);
		cursor.close(); // consumer walks away: the parked producer must observe the close and stop
		producer.join(5_000);
		assertFalse(producer.isAlive(), "consumer close must unblock a parked producer");
		assertTrue(producerStopped.get(), "the producer observed the closed exchange");
	}

	@Test
	void producerFailurePropagatesToTheConsumer() {
		NativeSlotLayout layout = layout(1);
		RowState row = row(layout);
		LmdbNativeHedgeExchange exchange = new LmdbNativeHedgeExchange(1, 4, 2);
		long[] slots = new long[] { 7L };
		assertTrue(exchange.offerRow(slots));
		exchange.fail(new IllegalStateException("backup broke"));
		LmdbNativeHedgeExchange.NativeHedgeExchangeCursor cursor = new LmdbNativeHedgeExchange.NativeHedgeExchangeCursor(
				row, exchange);
		assertTrue(cursor.next(), "rows packed before the failure still replay");
		assertThrows(IllegalStateException.class, cursor::next);
		cursor.close();
	}

	@Test
	void entryBindingsAreRestoredOnCursorClose() {
		NativeSlotLayout layout = layout(2);
		RowState row = row(layout);
		assertTrue(row.bind(0, 42L), "pre-bind an entry slot");
		long[] entry = row.slots.clone();
		LmdbNativeHedgeExchange exchange = new LmdbNativeHedgeExchange(2, 4, 2);
		exchange.offerRow(new long[] { 1L, 2L });
		exchange.finish();
		LmdbNativeHedgeExchange.NativeHedgeExchangeCursor cursor = new LmdbNativeHedgeExchange.NativeHedgeExchangeCursor(
				row, exchange);
		assertTrue(cursor.next());
		assertEquals(1L, row.slots[0], "the exchanged row overwrote the entry slot");
		assertFalse(cursor.next());
		cursor.close();
		assertEquals(entry[0], row.slots[0], "entry bindings restored after close");
		assertEquals(entry[1], row.slots[1]);
	}

	private static NativeSlotLayout layout(int slots) {
		LinkedHashMap<String, Integer> names = new LinkedHashMap<>();
		for (int slot = 0; slot < slots; slot++) {
			names.put("v" + slot, slot);
		}
		NativeSlotLayout layout = new NativeSlotLayout(names, null);
		layout.freeze(new ArrayList<>(names.keySet()));
		return layout;
	}

	private static RowState row(NativeSlotLayout layout) {
		RowState row = new RowState(null, layout, EmptyBindingSet.getInstance());
		java.util.Arrays.fill(row.slots, NativeLmdbQuerySource.UNKNOWN_ID);
		row.recomputeBoundMask();
		return row;
	}
}
